122		list, err := s.listStoredInstanceSettings(ctx, &FindInstanceSetting{Name: name})
123		if err != nil {
124			return nil, err
125		}
126		if len(list) == 0 {
127			return nil, nil
128		}
129		if len(list) > 1 {
130			return nil, errors.Errorf("found multiple stored instance settings with key %s", name)
131		}
132		return list[0], nil
133	}
