140	func (s *Store) GetInstanceSetting(ctx context.Context, find *FindInstanceSetting) (*storepb.InstanceSetting, error) {
141		if key, ok := storepb.InstanceSettingKey_value[find.Name]; ok {
142			if setting := s.getDeploymentInstanceSetting(storepb.InstanceSettingKey(key)); setting != nil {
143				return setting, nil
144			}
145		}
146		if cache, ok := s.instanceSettingCache.Get(ctx, find.Name); ok {
147			instanceSetting, ok := cache.(*storepb.InstanceSetting)
148			if ok {
149				return instanceSetting, nil
150			}
151		}
152	
153		list, err := s.ListInstanceSettings(ctx, find)
154		if err != nil {
155			return nil, err
156		}
157		if len(list) == 0 {
158			return nil, nil
159		}
160		if len(list) > 1 {
161			return nil, errors.Errorf("found multiple instance settings with key %s", find.Name)
162		}
163		return list[0], nil
164	}
